import { diffHeap, diffStack } from "../../../code/trace";
import { DragTracker } from "./drag-tracker";
import { createCodeAreaView, createHeapFunctionView, createShallowArrayView, createShallowObjectView, createShallowStackFrameView } from "../../view-module";
export class StepRenderer {
    constructor(zoomService, stackFrameShowHideTracker, stackLayouter, heapLayouter, consoleLayouter) {
        this.zoomService = zoomService;
        this.stackFrameShowHideTracker = stackFrameShowHideTracker;
        this.stackLayouter = stackLayouter;
        this.heapLayouter = heapLayouter;
        this.consoleLayouter = consoleLayouter;
        this.dragTracker = new DragTracker();
        this.heapViewIdMap = new Map();
        this.stackViewIdMap = new Map();
        this.lastRenderedStep = null;
    }
    clear() {
        this.zoomService.resetZoom();
        this.stackLayouter.clear();
        this.heapLayouter.clear();
        this.consoleLayouter.clear();
        this.heapViewIdMap = new Map();
        this.stackViewIdMap = new Map();
        this.lastRenderedStep = null;
    }
    renderStep(step) {
        // stop tracking heap views and frame views which existed in the previous step
        // but do not exist in this step
        if (this.lastRenderedStep !== null) {
            const heapDiff = diffHeap(this.lastRenderedStep, step);
            heapDiff.destroyed.forEach(id => this.heapViewIdMap.delete(id));
            const stackDiff = diffStack(this.lastRenderedStep, step);
            stackDiff.destroyed.forEach(id => this.stackViewIdMap.delete(id));
        }
        // create new heap and frame views if needed
        step.stack_frames.forEach(frame => this.maybeCreateFrameView(frame.frame_id, frame));
        Object.keys(step.heap).forEach(id => this.maybeCreateHeapElementView(id, step.heap[id]));
        // patch heap views so that dragging works as expected even
        // if the scene is zoomed
        for (const view of this.heapViewIdMap.values()) {
            this.zoomService.patchViewForZoom(view);
        }
        // patch heap views to keep track of their positions
        // if they are dragged by the user
        for (const view of this.heapViewIdMap.values()) {
            this.dragTracker.trackDrag(view);
        }
        // patch stack frame views so they react to "show/hide" clicks
        for (const [stackFrameView, _] of this.stackViewIdMap.values()) {
            this.stackFrameShowHideTracker.onToggleVisibility(stackFrameView, intention => {
                stackFrameView.setHidden(intention === "hide");
                this.renderStep(this.lastRenderedStep);
            });
        }
        // rerender the stack (code view + frame view)
        this.stackLayouter.rerender(step.stack_frames, this.stackViewIdMap);
        const fixedViews = [];
        // reset the position of heap views which the user has dragged
        for (const view of this.heapViewIdMap.values()) {
            if (this.dragTracker.hasTrackedPosition(view)) {
                this.dragTracker.moveToTrackedPosition(view);
                fixedViews.push(view);
            }
        }
        // rerender the heap views (including connections)
        const onlyStackFrameMap = new Map(Array.from(this.stackViewIdMap.entries()).map(([id, [stackFrameView, codeAreaView]]) => [id, stackFrameView]));
        this.heapLayouter.rerender(step, this.heapViewIdMap, onlyStackFrameMap, fixedViews);
        // rerender the console
        this.consoleLayouter.rerender(step.stdout, step.exception_message);
        this.lastRenderedStep = step;
    }
    maybeCreateHeapElementView(id, element) {
        const viewOrUndefined = this.heapViewIdMap.get(id);
        if (viewOrUndefined)
            return viewOrUndefined;
        let view;
        switch (element.kind) {
            case "array":
                view = createShallowArrayView(element);
                break;
            case "function":
                view = createHeapFunctionView(element.code);
                break;
            case "object":
                view = createShallowObjectView(element);
                break;
            default:
                element;
                throw new Error("getView: heap element has unknown kind");
        }
        this.heapViewIdMap.set(id, view);
        return view;
    }
    maybeCreateFrameView(id, frame) {
        const viewsOrUndefined = this.stackViewIdMap.get(id);
        if (viewsOrUndefined)
            return viewsOrUndefined;
        const stackFrameView = createShallowStackFrameView(frame);
        const codeAreaView = createCodeAreaView(frame.function_code, frame.code_line_start, frame.code_col_start, frame.code_line_end, frame.code_col_end);
        const result = [
            stackFrameView,
            codeAreaView
        ];
        this.stackViewIdMap.set(id, result);
        return result;
    }
}
