export const meta = {
    docs: {
        description: "Forbid getters and setters"
    },
    schema: []
};
export function create(context) {
    return {
        Property(node) {
            if (node.kind === "get" || node.kind === "set") {
                context.report({
                    node: node,
                    message: "The use of getters/setters is not allowed"
                });
            }
        }
    };
}
